// Turn the fetched emails and events into tagged data for the AI.
// Everything from an email or invite is written by someone else, so it goes inside
// <untrusted_email> / <untrusted_event> tags and is cleaned first:
//  - links become [link: domain], so the AI can't copy a link into the brief
//  - < > become ‹ ›, so no text can close or fake a tag
//  - { } become ( ), which the AI node would otherwise read as template fields
const settings = $('Your settings').first().json;
const tz = $now.zoneName;   // follows the workflow's timezone setting
const BODY_CAP = 1500;      // characters of each email body the AI sees

const clean = s => String(s == null ? '' : s)
  .replace(/https?:\/\/([^\s\/<>"'()\[\]]+)[^\s<>"'()\[\]]*/gi, (_, host) => `[link: ${host.toLowerCase()}]`)
  .replace(/\bwww\.[^\s<>"'()\[\]]+/gi, '[link]')
  .replace(/</g, '‹').replace(/>/g, '›')
  .replace(/\{/g, '(').replace(/\}/g, ')');

// Drop the quoted history under a reply so the cap is spent on the new message.
const newPart = t => String(t || '')
  .split(/\r?\n/).filter(l => !/^\s*>/.test(l)).join('\n')
  .split(/\n\s*On .{0,200}wrote:\s*\n/)[0];

const emails = $('Recent emails').all()
  .map(i => i.json)
  .filter(m => m && m.id)
  .map((m, n) => {
    const from = (m.from && (m.from.text || '')) || m.From || '';
    const subject = m.subject || m.Subject || '(no subject)';
    const body = newPart(m.text || m.snippet || '').replace(/\s+/g, ' ').trim().slice(0, BODY_CAP);
    return `<untrusted_email id="${n + 1}">\nFrom: ${clean(from)}\nSubject: ${clean(subject)}\nBody: ${clean(body)}\n</untrusted_email>`;
  });

const events = $("Today's calendar").all()
  .map(i => i.json)
  .filter(e => e && (e.id || e.summary))
  .map((e, n) => {
    const start = e.start && (e.start.dateTime || e.start.date);
    const end = e.end && (e.end.dateTime || e.end.date);
    const time = e.start && e.start.dateTime
      ? `${DateTime.fromISO(start).setZone(tz).toFormat('HH:mm')}–${DateTime.fromISO(end).setZone(tz).toFormat('HH:mm')}`
      : 'All day';
    const who = (e.attendees || []).map(p => p.displayName || p.email).filter(Boolean).slice(0, 8).join(', ');
    return `<untrusted_event id="${n + 1}">\nTime: ${time}\nTitle: ${clean(e.summary || '(no title)')}${who ? '\nWith: ' + clean(who) : ''}${e.location ? '\nWhere: ' + clean(e.location) : ''}\n</untrusted_event>`;
  });

return [{ json: {
  name: settings.your_name,
  email: settings.your_email,
  date: $now.toFormat('cccc d LLLL yyyy'),
  email_count: emails.length,
  event_count: events.length,
  emails_text: emails.length ? emails.join('\n\n') : 'No new emails.',
  events_text: events.length ? events.join('\n\n') : 'No meetings today.',
} }];

// Turn the AI's plain-text brief into a simple HTML email.
const pack = $('Pack emails and meetings').first().json;
const text = ($json.text || $json.output || '').trim();
// The brief never carries live links: strip any the AI wrote anyway.
const safe = text.replace(/https?:\/\/\S+/gi, '[link removed]').replace(/\bwww\.\S+/gi, '[link removed]');
if (!text) {
  // Stop here so an empty brief is never emailed. Usually the model ran out of tokens: raise Max Tokens in the model node.
  throw new Error('The AI returned an empty brief. Raise the maximum tokens in the model node and run again.');
}
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
let html = '', inList = false;
for (const raw of safe.split('\n')) {
  const line = raw.trimEnd();
  if (line.startsWith('- ')) {
    if (!inList) { html += '<ul>'; inList = true; }
    html += `<li>${inline(line.slice(2))}</li>`;
    continue;
  }
  if (inList) { html += '</ul>'; inList = false; }
  if (line.startsWith('## ')) html += `<h3 style="margin:20px 0 6px">${inline(line.slice(3))}</h3>`;
  else if (line.trim()) html += `<p style="margin:6px 0">${inline(line)}</p>`;
}
if (inList) html += '</ul>';
return [{ json: {
  to: pack.email,
  subject: `Your morning brief · ${pack.date}`,
  html: `<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.5;color:#1d1d24;max-width:640px">${html}</div>`,
} }];
